import * as z from 'zod';

/**
 * The private overlay (docs/CLUSTERING.md §4.1, phase C1).
 *
 * The control plane allocates one /32 per managed node and computes a hub-plus-LAN peer graph.
 * Only public keys travel: the private key is generated by the root helper on the node and never
 * leaves it. Bring-your-own networks and host-provisioned WireGuard stay `external` and receive
 * no managed peer list.
 */

export const nodeNetworkModes = ['yoal', 'external', 'edge'] as const;
export type NodeNetworkMode = (typeof nodeNetworkModes)[number];
export const nodeNetworkModeSchema = z.enum(nodeNetworkModes);

/** WireGuard interface defaults; a path probe may lower the MTU to 1280. */
export const DEFAULT_OVERLAY_CIDR = '10.88.0.0/22';
export const DEFAULT_WG_PORT = 51820;
export const DEFAULT_WG_MTU = 1420;
export const WG_KEEPALIVE_SECONDS = 25;

/** A WireGuard public key is 32 bytes, base64 with the trailing `=`. */
export const wireguardPublicKeySchema = z
	.string()
	.trim()
	.regex(/^[A-Za-z0-9+/]{43}=$/, 'Use a base64 WireGuard public key.');

export const overlayAddressSchema = z
	.string()
	.trim()
	.regex(/^(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}$/, 'Use an IPv4 address.');

export const wireguardPeerSchema = z.object({
	/** The node this peer represents; a hub peer carries every node routed through it. */
	nodeId: z.string().min(1).max(100),
	publicKey: wireguardPublicKeySchema,
	/** `host:port` or null for a peer that dials out and is learned from its handshake. */
	endpoint: z.string().max(253).nullable().default(null),
	/** Every /32 this peer is allowed to route (cryptokey routing). */
	allowedIps: z.array(z.string().regex(/^(?:\d{1,3}\.){3}\d{1,3}\/32$/)).min(1).max(64),
	persistentKeepalive: z.number().int().min(0).max(65_535).default(WG_KEEPALIVE_SECONDS),
});
export type WireguardPeer = z.infer<typeof wireguardPeerSchema>;

export const wireguardStateSchema = z.object({
	mode: nodeNetworkModeSchema,
	address: overlayAddressSchema.nullable().default(null),
	cidr: z.string().max(32).nullable().default(null),
	mtu: z.number().int().min(1280).max(1420).default(DEFAULT_WG_MTU),
	listenPort: z.number().int().min(1).max(65_535).default(DEFAULT_WG_PORT),
	peers: z.array(wireguardPeerSchema).max(64).default([]),
});
export type WireguardState = z.infer<typeof wireguardStateSchema>;

/** Added to the join request by the managed installer; absent means a BYO/external node. */
export const nodeJoinNetworkSchema = z.object({
	networkMode: z.enum(['yoal', 'external']).default('external'),
	wireguardPublicKey: wireguardPublicKeySchema.optional(),
});
export type NodeJoinNetwork = z.infer<typeof nodeJoinNetworkSchema>;

/** The helper's `wg show <if> dump`, reduced to public data. */
export const wireguardPeerStatusSchema = z.object({
	publicKey: wireguardPublicKeySchema,
	endpoint: z.string().max(253).nullable().default(null),
	latestHandshakeAt: z.string().max(40).nullable().default(null),
	rxBytes: z.number().int().nonnegative().default(0),
	txBytes: z.number().int().nonnegative().default(0),
});
export type WireguardPeerStatus = z.infer<typeof wireguardPeerStatusSchema>;

export const wireguardStatusSchema = z.object({
	interface: z.string().min(1).max(32),
	peers: z.array(wireguardPeerStatusSchema).max(64).default([]),
});
export type WireguardStatus = z.infer<typeof wireguardStatusSchema>;
